arguments.content:
/*
 * Tree files support: store the data of an export in a tree of small
 * block files rather than in a single large file. This is useful on
 * filesystems that do not handle large files well (fuse/ftpfs, davfs,
 * other network filesystems).
 *
 * The tree is rooted at the export name (which is a directory in this
 * mode). Every directory holds at most TREEDIRSIZE entries: subdirectories
 * named TREEXXXX, and block files named FILEXXXX in the leaf directories.
 * Each block file holds TREEPAGESIZE bytes of data; the nesting level is
 * chosen such that the tree can hold filesize bytes in total.
 */

#include <fcntl.h>
#include <limits.h> /* for PATH_MAX */
#include <inttypes.h>
#include <stdio.h>
#include <unistd.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "config.h"
#include "cliserv.h"
#include "treefiles.h"
#include "nbd-debug.h"

/**
 * Recursively construct the path of the block file holding the data at
 * offset pos, appending it to the buffer in name.
 *
 * @param name buffer to append the path to; the string already contains
 * the name of the directory to start from
 * @param lenmax size of the buffer in name
 * @param size the size of the (sub)tree we're currently constructing
 * @param pos the byte offset in the export for which to construct the path
 * @param ppos internal recursion state; the block number we're currently
 * processing, divided by the number of blocks in the subtree below us
 */
void construct_path(char* name, int lenmax, off_t size, off_t pos, off_t* ppos) {
	if (lenmax < 10)
		err("Char buffer overflow. This is likely a bug.");

	if (size < TREEDIRSIZE*TREEPAGESIZE) {
		/* we are done, add filename */
		snprintf(name, lenmax, "/FILE%04" PRIX64, (pos/TREEPAGESIZE) % TREEDIRSIZE);
		*ppos = pos / (TREEPAGESIZE*TREEDIRSIZE);
	} else {
		construct_path(name+9, lenmax-9, size/TREEDIRSIZE, pos, ppos);
		char buffer[10];
		snprintf(buffer, sizeof(buffer), "/TREE%04jX", (intmax_t)(*ppos % TREEDIRSIZE));
		memcpy(name, buffer, 9); /* copy into string without trailing zero */
		*ppos /= TREEDIRSIZE;
	}
}

/**
 * Delete the block file holding the data at offset pos, if it exists.
 * Used to implement TRIM on treefiles exports.
 *
 * @param name the name of the tree root directory
 * @param size the total size of the export
 * @param pos the byte offset in the export
 */
void delete_treefile(char* name, off_t size, off_t pos) {
	char filename[PATH_MAX];
	off_t ppos;

	strncpy(filename, name, PATH_MAX-1);
	filename[PATH_MAX-1] = '\0';
	construct_path(filename+strlen(name), PATH_MAX-strlen(name)-1, size, pos, &ppos);

	DEBUG("Deleting treefile: %s", filename);

	if (unlink(filename) == -1)
		DEBUG("Deleting failed: %s", strerror(errno));
}

/**
 * Create all directories in a path, as far as they don't exist yet.
 *
 * @param path the path to create; every component up to (but not
 * including) the last one is created as a directory
 */
void mkdir_path(char* path) {
	char *subpath = path+1;

	while ((subpath = strchr(subpath, '/'))) {
		*subpath = '\0'; /* path is modified in place with terminating null char instead of slash */
		if (mkdir(path, 0700) == -1) {
			if (errno != EEXIST)
				err("Path access error! %m");
		}
		*subpath = '/';
		subpath++;
	}
}

/**
 * Open the block file holding the data at offset pos, creating it (and
 * any directories leading up to it) if it does not exist yet and we're
 * allowed to write. If it does not exist and we're read-only, open a
 * temporary, zero-filled file instead, so that reads of unwritten blocks
 * return zeroes.
 *
 * @param name the name of the tree root directory
 * @param mode O_RDONLY or O_RDWR
 * @param size the total size of the export
 * @param pos the byte offset in the export
 * @param mutex a mutex to serialize file creation with other threads
 * @return a file descriptor for the block file
 */
int open_treefile(char* name, mode_t mode, off_t size, off_t pos, pthread_mutex_t* mutex) {
	char filename[PATH_MAX];
	off_t ppos;

	strncpy(filename, name, PATH_MAX-1);
	filename[PATH_MAX-1] = '\0';
	construct_path(filename+strlen(name), PATH_MAX-strlen(name)-1, size, pos, &ppos);

	DEBUG("Accessing treefile %s (offset %llu of %llu)", filename, (unsigned long long)pos, (unsigned long long)size);

	pthread_mutex_lock(mutex);
	int handle = open(filename, mode, 0600);
	if (handle < 0 && errno == ENOENT) {
		if (mode & O_RDWR) {
			DEBUG("Creating new treepath");

			mkdir_path(filename);
			handle = open(filename, O_RDWR|O_CREAT, 0600);
			if (handle < 0) {
				err("Error opening tree block file %m");
			}
		} else {
			DEBUG("Creating a dummy tempfile for reading");
			char tmpname[] = "dummy-XXXXXX";
			mode_t oldmode = umask(077);
			handle = mkstemp(tmpname);
			umask(oldmode);
			if (handle > 0) {
				unlink(tmpname); /* File will stick around whilst FD open */
			} else {
				err("Error opening tree block file %m");
			}
		}
		char* n = "\0";
		if (lseek(handle, TREEPAGESIZE-1, SEEK_SET) < 0) {
			err("Could not create tree file!\n");
		}
		ssize_t c = write(handle, n, 1);
		if (c < 1) {
			err("Error setting tree block file size %m");
		}
	}
	pthread_mutex_unlock(mutex);
	return handle;
}

